// Fixed DOM pools: no per-hit nodes, and no screen-space drift when the camera moves.
export class CombatLabels {
 constructor(root){this.root=root;this.cursor=0;this.bars=Array.from({length:8},()=>{const node=document.createElement('div');node.className='troop-health';node.innerHTML='<i></i>';node.hidden=true;root.append(node);return {node,fill:node.firstElementChild};});this.numbers=Array.from({length:24},()=>{const node=document.createElement('span');node.className='hit-number';node.hidden=true;root.append(node);return {node,life:0};});}
 clear(){for(const bar of this.bars)bar.node.hidden=true;for(const n of this.numbers){n.life=0;n.node.hidden=true;}this.cursor=0;}
 emit(event,game){if(!event.damage||!['hit','special-hit','counter-hit','execution-hit','hurt','parry'].includes(event.type))return;const n=this.numbers[this.cursor++%this.numbers.length],enemy=game.targets().find(e=>e.id===event.enemyId)||game.enemy,player=event.target==='player';Object.assign(n,{x:event.x,z:event.z,y:player?2.1:enemy.kindId==='wolf'||game.spec.id==='wolf'&&!game.campaign?1.45:enemy.kindId==='oni'||game.spec.id==='oni'&&!game.campaign?3.5:2.65,life:.8,total:.8,side:(this.cursor%3-1)*.22});n.node.textContent=player?`−${event.damage}`:String(event.damage);n.node.className=`hit-number${player?' received':event.heavy?' strong':''}`;}
 update(dt,game,world,active){if(!active){this.clear();return;}const targets=game.campaign?game.enemies:[];
  this.bars.forEach((bar,i)=>{const e=targets[i];if(!e||e.hp<=0||Math.hypot(e.x-game.player.x,e.z-game.player.z)>18){bar.node.hidden=true;return;}const point=world.screenPoint(e.x,e.kindId==='wolf'?1.6:e.kindId==='oni'?3.8:2.9,e.z);bar.node.hidden=!point.visible;bar.node.style.left=`${point.x*100}%`;bar.node.style.top=`${point.y*100}%`;bar.fill.style.transform=`scaleX(${e.hp/e.maxHp})`;bar.node.classList.toggle('selected',e===game.enemy);bar.node.classList.toggle('broken',e.exposed);});
  for(const n of this.numbers){n.life=Math.max(0,n.life-dt);if(n.life===0){n.node.hidden=true;continue;}const age=1-n.life/n.total,point=world.screenPoint(n.x+n.side,n.y+age*.75,n.z);n.node.hidden=!point.visible;n.node.style.left=`${point.x*100}%`;n.node.style.top=`${point.y*100}%`;n.node.style.opacity=String(Math.min(1,n.life/.22));}
 }
 snapshot(){return{bars:this.bars.filter(b=>!b.node.hidden).length,numbers:this.numbers.filter(n=>!n.node.hidden).length,capacity:this.numbers.length};}
}
